                            <Button
                                aria-expanded={!!rootMenu}
                                aria-haspopup="menu"
                                key={record.id}
                                onClick={handleRootCrumb}
                                size="small"
                                variant="text"
                            >
                                {record.label}
                            </Button>
                        ) : (
                            <Button
                                data-diagram-breadcrumb-index={recordIndex}
                                disabled={recordIndex === activeRecords.length - 1}
                                key={record.id}
                                size="small"
                                variant="text"
                            >
                                {record.label}
                            </Button>
                        );
                    })}
                </Breadcrumbs>
